<script setup lang="ts">
import RefreshButton from '@/components/RefreshButton.vue'
import { toRef } from 'vue'
import EditorExpandButton from '@/components/EditorExpandButton.vue'
import ExecutionModeSelect from '@/components/ExecutionModeSelect.vue'
import { useEditorExpansion } from '@/features/workspace/useEditorExpansion'
import { filingMode } from '@/app/siteMode'
import { openSiteAssistant } from '@/composables/useSiteAssistant'
import TryRunPanel from '@/components/TryRunPanel.vue'
import { previousTemplateVersions,restoreTemplateDraft } from '@/features/workspace/templateDraft'
import SubmissionResourceComparison from '@/components/SubmissionResourceComparison.vue'
import { computed,onBeforeUnmount,onMounted,ref,watch } from 'vue';import { useRoute,useRouter } from 'vue-router';import { useQuery } from '@tanstack/vue-query';import { ElMessage } from '@/app/messages';import AppHeader from '@/components/AppHeader.vue';import AsyncState from '@/components/AsyncState.vue';import ProblemStatement from '@/components/ProblemStatement.vue';import CodeEditor from '@/components/CodeEditor.vue';import JudgeStatusBadge from '@/components/JudgeStatusBadge.vue';import SubmissionAiAnalysis from '@/components/SubmissionAiAnalysis.vue';import { getCapabilities,getProblem,getTemplate } from '@/api/question';import { getSubmission,recoverSubmission,submitCode } from '@/api/submission';import { ApiError,readableError } from '@/api/errors';import type { ExecutionMode,Id,LanguageId,Submission } from '@/api/types';import { useSession } from '@/composables/useSession';import { usePreferencesStore } from '@/stores/preferences';import { draftKey,listenDrafts,readDraft,writeDraft,type Draft as StoredDraft } from '@/features/workspace/drafts';import { loadRecentResult,pendingSubmissionKey,saveRecentResult,type RecentSubmissionResult } from '@/features/submissions/recentResult';import { formatDiagnostic } from '@/features/submissions/diagnostics';import { useWorkspaceSplit } from '@/features/workspace/useWorkspaceSplit'
const route=useRoute(),router=useRouter(),session=useSession(),prefs=usePreferencesStore();const id=computed(()=>String(route.params.problemId));
const problem=useQuery({queryKey:computed(()=>['public','problem',id.value]),queryFn:({signal})=>getProblem(id.value,signal)});const caps=useQuery({queryKey:computed(()=>['public','capabilities',id.value]),queryFn:({signal})=>getCapabilities(id.value,signal)});
const language=ref<LanguageId>('java'),executionMode=ref<ExecutionMode>('ACM'),code=ref(''),templateVersion=ref(''),draftState=ref<'loading'|'saved'|'saving'|'error'>('loading'),draftError=ref('');let saveTimer:number|undefined;let requestSequence=0;const activeRequest=ref(0);const submissionId=ref<Id|''>('');const submitBusy=ref(false);const uncertain=ref<{requestId:string;code:string}|null>(null);const recentResult=ref<RecentSubmissionResult|null>(null)
const codeBytes=computed(()=>new TextEncoder().encode(code.value).length)
const activeDraftKey=ref('');const draftRevision=ref(0),draftConflict=ref<StoredDraft|null>(null);let stopDraftListener=()=>{}
const capability=computed(()=>caps.data.value?.languages.find(v=>v.id===language.value));const enabledLanguages=computed(()=>caps.data.value?.languages??[]);const availableModes=computed<ExecutionMode[]>(()=>capability.value?.modes?.length?capability.value.modes:[caps.data.value?.mode??'ACM'])
const submissionScope=computed(()=>{const userId=session.user.value?.id,questionId=caps.data.value?.questionId;return userId&&questionId?{userId,questionId}:null})
watch(submissionScope,value=>{if(!value){submissionId.value='';recentResult.value=null;return}submissionId.value=sessionStorage.getItem(pendingSubmissionKey(value.userId,value.questionId))??'';recentResult.value=loadRecentResult(value.userId,value.questionId)},{immediate:true})
watch(()=>caps.data.value,value=>{if(!value)return;const available=value.languages.filter(v=>v.enabled);const previous=localStorage.getItem(`nemooj.lang.${value.questionId}`) as LanguageId|null;language.value=(available.find(v=>v.id===previous)?.id??available.find(v=>v.id===prefs.preferredLanguage)?.id??value.recommendedLanguage??available[0]?.id??'java');const modes=available.find(v=>v.id===language.value)?.modes??[value.mode];const preferred=localStorage.getItem(`nemooj.mode.${value.questionId}`) as ExecutionMode|null;executionMode.value=modes.includes(preferred as ExecutionMode)?preferred as ExecutionMode:modes.includes(value.mode)?value.mode:modes[0]??'ACM'},{immediate:true})
watch(language,()=>{if(!availableModes.value.includes(executionMode.value))executionMode.value=availableModes.value[0]??'ACM'})
watch([()=>caps.data.value,language,executionMode],async([value,lang,mode])=>{
  if(!value)return
  const seq=++requestSequence
  activeRequest.value=seq;activeDraftKey.value='';draftState.value='loading';draftConflict.value=null
  try{
    const tpl=await getTemplate(id.value,lang,value.problemVersion,mode)
    if(seq!==activeRequest.value)return
    const owner=session.user.value?.id??'guest'
    const key=draftKey(owner,tpl.questionId,tpl.problemVersion,lang,mode,tpl.templateVersion)
    let saved=await readDraft(key)
    if(!saved||restoreTemplateDraft(saved.code,tpl.code,lang,mode)===tpl.code){
      for(const previous of previousTemplateVersions(tpl.templateVersion,mode)){
        const legacy=await readDraft(draftKey(owner,tpl.questionId,tpl.problemVersion,lang,mode,previous))
        if(!legacy)continue
        if(restoreTemplateDraft(legacy.code,tpl.code,lang,mode)!==tpl.code){saved=legacy;break}
        if(!saved)saved=legacy
      }
    }
    if(seq!==activeRequest.value)return
    activeDraftKey.value=key;templateVersion.value=tpl.templateVersion
    if(saved){code.value=restoreTemplateDraft(saved.code,tpl.code,lang,mode);draftRevision.value=saved.key===key?saved.revision:0}
    else{code.value=tpl.code;draftRevision.value=0}
    draftState.value='saved'
  }catch(e){if(seq===activeRequest.value){draftState.value='error';draftError.value=readableError(e)}}
},{immediate:true})
watch(code,()=>{if(draftState.value==='loading')return;draftState.value='saving';window.clearTimeout(saveTimer);saveTimer=window.setTimeout(saveDraft,500)})
async function saveDraft(){const key=activeDraftKey.value;if(!key)return;try{const saved=await writeDraft({key,code:code.value,templateVersion:templateVersion.value});draftRevision.value=saved.revision;draftState.value='saved'}catch(e){draftState.value='error';draftError.value=readableError(e)}}
async function resolveConflict(useExternal:boolean){const external=draftConflict.value;if(!external)return;if(useExternal){code.value=external.code;draftRevision.value=external.revision;templateVersion.value=external.templateVersion;draftState.value='saved'}else await saveDraft();draftConflict.value=null}
function changeLanguage(next:LanguageId){void saveDraft();language.value=next;prefs.preferredLanguage=next;const questionId=caps.data.value?.questionId;if(questionId)localStorage.setItem(`nemooj.lang.${questionId}`,next)}
function changeMode(next:ExecutionMode){if(!availableModes.value.includes(next))return;void saveDraft();executionMode.value=next;const questionId=caps.data.value?.questionId;if(questionId)localStorage.setItem(`nemooj.mode.${questionId}`,next)}
const submission=useQuery<Submission>({queryKey:computed(()=>['submission',session.user.value?.id,submissionId.value]),queryFn:({signal})=>getSubmission(submissionId.value,signal),enabled:computed(()=>Boolean(submissionId.value&&session.user.value)),refetchInterval:q=>{const d=q.state.data;if(d&&(d.status===2||d.status===3))return false;if(!d)return 1000;const elapsed=Date.now()-new Date(d.createTime).getTime();return elapsed<30_000?1000:elapsed<120_000?2000:elapsed<300_000?5000:10_000}})
const previousResult=computed(()=>recentResult.value&&String(recentResult.value.id)!==String(submissionId.value)?recentResult.value:null)
watch(()=>submission.data.value,value=>{const scope=submissionScope.value;if(!scope||!value||(value.status!==2&&value.status!==3))return;recentResult.value=saveRecentResult(scope.userId,scope.questionId,value);sessionStorage.removeItem(pendingSubmissionKey(scope.userId,scope.questionId))})
async function submit(){if(filingMode){ElMessage.info({ message: '当前仅开放题库浏览' });return}if(!session.user.value){await saveDraft();await router.push({path:'/login',query:{returnTo:route.fullPath}});return}if(session.user.value.userRole==='ban'){ElMessage.error({ message: '当前账号已被限制提交' });return}const c=caps.data.value,cap=capability.value;if(!c||!cap?.enabled||!availableModes.value.includes(executionMode.value)||submitBusy.value)return;const pendingKey=pendingSubmissionKey(session.user.value.id,c.questionId);const bytes=new TextEncoder().encode(code.value).length;if(bytes>cap.maxCodeBytes){ElMessage.error({ message: `代码大小 ${bytes} 字节，超过上限 ${cap.maxCodeBytes} 字节` });return}const snapshot={requestId:crypto.randomUUID(),code:code.value};submitBusy.value=true;try{const sid=await submitCode({questionId:id.value,language:language.value,executionMode:executionMode.value,code:snapshot.code,problemVersion:c.problemVersion,clientRequestId:snapshot.requestId});submissionId.value=sid;sessionStorage.setItem(pendingKey,sid);uncertain.value=null}catch(e){if(e instanceof ApiError&&(e.kind==='network'||e.kind==='timeout'||e.kind==='protocol'||(e.kind==='http'&&(e.status??0)>=500))){uncertain.value=snapshot;ElMessage.warning({ message: '提交结果尚未确认，正在按请求标识查询' });try{const found=await recoverSubmission(snapshot.requestId);if(found){submissionId.value=found.id;sessionStorage.setItem(pendingKey,found.id)}else ElMessage.error({ message: readableError(e) })}catch{ElMessage.error({ message: readableError(e) })}}else ElMessage.error({ message: readableError(e) })}finally{submitBusy.value=false}}
async function leave(){await saveDraft();await session.logout();await router.push('/problems')}onMounted(()=>{stopDraftListener=listenDrafts(async event=>{if(event.key!==activeDraftKey.value||event.revision<=draftRevision.value)return;const external=await readDraft(event.key);if(!external)return;if(external.code===code.value){draftRevision.value=external.revision}else draftConflict.value=external})});onBeforeUnmount(()=>{stopDraftListener();window.clearTimeout(saveTimer);void saveDraft()})
const splitEl=ref<HTMLElement|null>(null),codePaneEl=ref<HTMLElement|null>(null);const {problemWidth,problemPercent,visibleResultHeight,resultPixels,maxResultHeight,beginDrag,onVerticalKeydown,onHorizontalKeydown}=useWorkspaceSplit(splitEl,codePaneEl)
const codeEditor=ref<InstanceType<typeof CodeEditor>>()
const {editorExpanded,editorFontSize,toggleEditor}=useEditorExpansion(toRef(prefs,'fontSize'),id)
function navigateAnalyzedLine(line:number,analyzedId:string){
  const analyzed=submission.data.value
  if(analyzed?.id===analyzedId&&analyzed.code===code.value)codeEditor.value?.revealLine(line)
  else void router.push({path:`/submissions/${analyzedId}`,query:{line}})
}
</script>
<template><div class="workspace user-shell" :class="{ 'editor-expanded': editorExpanded }"><AppHeader :user="session.user.value" :state="session.state.value" compact @logout="leave"/><div class="workspace-main"><AsyncState class="workspace-state" :loading="problem.isPending.value||caps.isPending.value" :error="problem.isError.value?readableError(problem.error.value):caps.isError.value?readableError(caps.error.value):undefined" @retry="problem.refetch();caps.refetch()"><template v-if="problem.data.value&&caps.data.value"><main ref="splitEl" class="split" :style="{ '--problem-width': problemPercent }"><section class="problem-pane"><ProblemStatement :problem="problem.data.value" :capability="capability" :mode="executionMode"/></section><div class="splitter vertical" role="separator" aria-orientation="vertical" aria-label="调整题目描述宽度" aria-valuemin="0" aria-valuemax="100" :aria-valuenow="Math.round(problemWidth)" tabindex="0" title="拖动调整题目描述宽度；也可用左右方向键" @pointerdown="beginDrag($event, 'vertical')" @keydown="onVerticalKeydown"><span class="grip" aria-hidden="true" /></div><section ref="codePaneEl" class="code-pane" :style="{ '--result-height': resultPixels }"><div class="toolbar"><el-select :model-value="language" aria-label="编程语言" @change="changeLanguage"><el-option v-for="item in enabledLanguages" :key="item.id" :value="item.id" :label="item.displayName" :disabled="!item.enabled"><span>{{item.displayName}}</span><span v-if="!item.enabled" class="disabled-reason">{{item.disabledReason}}</span></el-option></el-select><ExecutionModeSelect :model-value="executionMode" :available-modes="availableModes" @update:model-value="changeMode"/><span class="toolbar-spacer" aria-hidden="true"/><EditorExpandButton :expanded="editorExpanded" @toggle="toggleEditor"/><el-button v-if="session.user.value" @click="openSiteAssistant('feedback',problem.data.value.problemNo ?? undefined)">反馈</el-button><el-button @click="prefs.editorTheme=prefs.editorTheme==='vs'?'vs-dark':'vs'">{{prefs.editorTheme==='vs'?'深色编辑器':'浅色编辑器'}}</el-button><TryRunPanel v-if="session.user.value?.userRole=== 'user' &amp;&amp; !filingMode" :problem="problem.data.value" :language="language" :mode="executionMode" :code="code" :disabled="!capability?.enabled || submitBusy"/><el-button type="primary" :loading="submitBusy" :disabled="filingMode||!capability?.enabled||!availableModes.includes(executionMode)" @click="submit">{{filingMode?'暂未开放提交':submissionId?'再次提交':'提交'}}</el-button></div><div class="editor-wrap"><CodeEditor ref="codeEditor" v-model="code" :language="language" :mode="executionMode" :problem-spec="problem.data.value.problemSpec" :document-key="`${caps.data.value.questionId}-${caps.data.value.problemVersion}-${language}-${executionMode}-${templateVersion}`" :theme="prefs.editorTheme" :font-size="editorFontSize" :expanded="editorExpanded" @request-restore="editorExpanded=false" @request-submit="submit" @request-save="saveDraft"/></div><el-alert v-if="draftConflict" class="conflict" title="另一标签页更新了这份草稿" type="warning" :closable="false"><el-button size="small" @click="resolveConflict(true)">使用另一标签页版本</el-button><el-button size="small" @click="resolveConflict(false)">保留当前版本</el-button></el-alert><div class="draft" :class="draftState==='error'?'bad':''"><span>{{draftState==='saving'?'草稿保存中…':draftState==='saved'?'草稿已保存':draftState==='error'?`草稿保存失败：${draftError}`:'正在恢复草稿…'}}</span><span class="completion-hint" title="输入时自动提示，也可以按 Ctrl+Space 手动打开建议">Ctrl+Space 补全</span><span>{{codeBytes}} / {{capability?.maxCodeBytes??'—'}} bytes</span></div><div class="splitter horizontal" role="separator" aria-orientation="horizontal" aria-label="调整判题结果高度" aria-valuemin="160" :aria-valuemax="maxResultHeight" :aria-valuenow="visibleResultHeight" tabindex="0" title="拖动调整判题结果高度；也可用上下方向键" @pointerdown="beginDrag($event, 'horizontal')" @keydown="onHorizontalKeydown"><span class="grip" aria-hidden="true" /></div><div class="result" aria-live="polite"><div class="result-head"><strong>本次提交</strong><div v-if="submissionId" class="result-actions"><RouterLink :to="`/submissions/${submissionId}`">#{{submissionId}}</RouterLink><span class="auto-watch">自动监视</span><RefreshButton size="small" :loading="submission.isFetching.value" @click="submission.refetch()">刷新结果</RefreshButton></div></div><div v-if="!submissionId" class="result-empty">提交后在这里查看判题状态。正式提交会计入记录。</div><AsyncState v-else :loading="submission.isPending.value" :error="submission.isError.value?readableError(submission.error.value):undefined" @retry="submission.refetch()"><template v-if="submission.data.value"><div class="result-data"><JudgeStatusBadge :status="submission.data.value.status" :verdict="submission.data.value.verdict||submission.data.value.judgeInfo?.message"/><span>耗时 {{submission.data.value.judgeInfo?.executedTime??'—'}} ms</span><span>内存 {{submission.data.value.judgeInfo?.executedMemory==null?'—':(submission.data.value.judgeInfo.executedMemory/1024).toFixed(1)}} MiB</span></div><SubmissionAiAnalysis v-if="session.user.value?.userRole === 'user'" :key="`${session.user.value.id}-${submissionId}`" :user-id="session.user.value.id" :submission-id="submissionId" :status="submission.data.value.status" :verdict="submission.data.value.verdict || submission.data.value.judgeInfo?.message" @navigate-line="line=>navigateAnalyzedLine(line,String(submissionId))"/><SubmissionResourceComparison v-if="session.user.value" :submission="submission.data.value"/><div v-if="submission.data.value.diagnostics" class="diagnostic"><strong>{{submission.data.value.diagnostics.phase==='compile'?'编译错误详情':'运行错误详情'}}</strong><pre>{{formatDiagnostic(submission.data.value.diagnostics.message)}}</pre><span v-if="submission.data.value.diagnostics.truncated">错误信息过长，已截断</span></div></template></AsyncState><div v-if="previousResult" class="previous-result"><strong>上次提交</strong><RouterLink :to="`/submissions/${previousResult.id}`">#{{previousResult.id}}</RouterLink><JudgeStatusBadge :status="previousResult.status" :verdict="previousResult.verdict"/><span>耗时 {{previousResult.executedTime??'—'}} ms</span><span>内存 {{previousResult.executedMemory==null?'—':(previousResult.executedMemory/1024).toFixed(1)}} MiB</span></div><SubmissionAiAnalysis v-if="!submissionId && recentResult && session.user.value?.userRole === 'user'" :key="`${session.user.value.id}-${recentResult.id}`" :user-id="session.user.value.id" :submission-id="String(recentResult.id)" :status="recentResult.status" :verdict="recentResult.verdict ?? undefined" @navigate-line="line=>navigateAnalyzedLine(line,String(recentResult!.id))"/></div></section></main></template></AsyncState></div></div></template>
<style scoped>
.workspace{height:100dvh;overflow:hidden;display:grid;grid-template-columns:var(--oj-sidebar-width) minmax(0,1fr);background:var(--oj-bg)}
.workspace-main,.workspace-state{height:100dvh;min-width:0}
.split{height:100dvh;display:grid;grid-template-columns:clamp(310px,var(--problem-width),calc(100% - 438px)) 8px minmax(430px,1fr)}
.problem-pane{min-width:0;overflow:auto;background:var(--oj-surface)}
.code-pane{min-width:0;min-height:0;position:relative;display:grid;grid-template-rows:58px minmax(260px,1fr) 30px 8px minmax(160px,var(--result-height));background:var(--oj-surface-soft)}
.splitter{position:relative;z-index:2;display:flex;align-items:center;justify-content:center;background:var(--oj-border);touch-action:none;outline:none;transition:background .15s}.splitter:hover,.splitter:focus-visible{background:var(--oj-primary)}.splitter.vertical{cursor:col-resize}.splitter.horizontal{cursor:row-resize}.splitter .grip{display:block;width:3px;height:28px;border-radius:4px;background:var(--oj-text-muted);opacity:.7}.splitter.horizontal .grip{width:28px;height:3px}.splitter:focus-visible{box-shadow:inset 0 0 0 2px var(--oj-primary)}
.conflict{position:absolute;z-index:8;right:12px;top:68px;width:min(420px,calc(100% - 24px));box-shadow:0 12px 34px rgba(0,0,0,.36)}
.toolbar{display:flex;align-items:center;gap:10px;padding:9px 14px;overflow-x:auto;overflow-y:hidden;scrollbar-width:thin;background:var(--oj-surface-raised);border-bottom:1px solid var(--oj-border)}.toolbar>*{flex-shrink:0}
.toolbar .el-select{width:145px}.toolbar .execution-mode{width:125px}.toolbar .toolbar-spacer{flex:1;min-width:0}
.editor-wrap{min-height:0;overflow:hidden;border-bottom:1px solid var(--oj-border)}
.draft{display:flex;justify-content:space-between;padding:6px 12px;font-size:11px;color:var(--oj-text-muted);background:var(--oj-surface-soft)}.draft.bad{color:var(--oj-danger)}
.result{min-height:0;padding:16px 18px;overflow:auto;background:var(--oj-surface)}.result-head{display:flex;justify-content:space-between}.result-actions{display:flex;align-items:center;gap:14px}.auto-watch{font-size:12px;color:var(--oj-text-muted)}.result-empty{color:var(--oj-text-muted);padding:40px;text-align:center}.result-data{display:flex;gap:24px;align-items:center;margin-top:24px}.diagnostic{margin-top:16px}.diagnostic pre{max-height:180px;overflow:auto;white-space:pre-wrap;word-break:break-word;margin:8px 0 0;padding:12px;border:1px solid #3b2a2f;border-radius:7px;background:#160f12;color:#ffb4b4;font:12px/1.55 ui-monospace,SFMono-Regular,Consolas,monospace}.diagnostic>span{font-size:11px;color:var(--oj-text-muted)}.previous-result{display:flex;align-items:center;gap:14px;margin-top:16px;padding-top:14px;border-top:1px solid var(--oj-border);font-size:12px;color:var(--oj-text-muted)}.disabled-reason{margin-left:8px;color:var(--oj-text-muted);font-size:11px}
@media(max-width:1080px){.workspace{height:auto;overflow:auto}.workspace-main,.workspace-state{height:auto}.split{height:auto;display:block}.splitter.vertical{display:none}.problem-pane{max-height:44vh;border-right:0;border-bottom:1px solid var(--oj-border)}.code-pane{height:calc(100dvh - 64px)}}
@media(max-width:900px){.workspace{display:block}.workspace-main{min-height:calc(100dvh - 64px)}}
@media(max-width:767px){.toolbar{flex-wrap:wrap;height:auto;overflow:visible}.splitter.horizontal{display:none}.code-pane{grid-template-rows:auto minmax(380px,1fr) 30px auto}.completion-hint{display:none}.result{min-height:180px}.result-data{flex-wrap:wrap;margin-top:20px}}
.workspace.editor-expanded{height:100dvh;overflow:hidden}
.editor-expanded .workspace-main{height:100%;min-height:0}
.editor-expanded .split{height:100%;display:block;min-height:0}
.editor-expanded .problem-pane,.editor-expanded .splitter,.editor-expanded .result{display:none}
.editor-expanded .code-pane{height:100%;grid-template-rows:58px minmax(0,1fr) 30px}
@media(max-width:900px){.workspace.editor-expanded{display:grid;grid-template-columns:minmax(0,1fr);grid-template-rows:64px minmax(0,1fr)}.editor-expanded .workspace-main{min-height:0}}
@media(max-width:767px){.editor-expanded .code-pane{grid-template-rows:auto minmax(0,1fr) 30px}.editor-expanded .toolbar{gap:8px;padding:8px}.editor-expanded .toolbar-spacer{display:none}.editor-expanded .editor-wrap :deep(.mobile-editor){min-height:0;resize:none}}
</style>
